package com.bank.jvm;

import java.math.BigDecimal;
import java.util.logging.*;

// Demonstrates a memory leak and early detection via heap trend monitoring.
public class LeakDemo {
    private static final Logger log = Logger.getLogger(LeakDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        HeapTrendMonitor monitor = new HeapTrendMonitor();

        try {
            long txnId = 0;
            while (true) {
                // Each "transfer" creates an audit record...
                AuditRecord rec = new AuditRecord("TXF-" + txnId,
                        "SAV2001", "CUR3001", new BigDecimal("50000"));
                // ...and LEAKS it into a static cache that is never pruned.
                AuditCache.store(rec);
                txnId++;

                if (txnId % 100_000 == 0) {
                    monitor.sampleAfterGc(AuditCache.size());
                }
            }
        } catch (OutOfMemoryError oom) {
            log.severe("OutOfMemoryError: leak filled the heap. Records retained: "
                    + AuditCache.size());
            log.severe("Analyze the auto-generated heap dump in Eclipse MAT (Dominator Tree).");
        }
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}

// ─── Would be in AuditRecord.java in a real project ───
class AuditRecord {
    private final String transferId; private final String from; private final String to;
    private final BigDecimal amount; private final long when; private final byte[] detail;
    AuditRecord(String id, String from, String to, BigDecimal amount) {
        this.transferId = id; this.from = from; this.to = to; this.amount = amount;
        this.when = System.currentTimeMillis();
        this.detail = new byte[1024]; // simulate a non-trivial record payload
    }
}

// ─── Would be in AuditCache.java in a real project ───
class AuditCache {
    // THE BUG: static map, grows forever, never evicts -> classic leak.
    private static final java.util.Map<String, AuditRecord> CACHE = new java.util.HashMap<>();
    static void store(AuditRecord r) { CACHE.put(keyOf(r), r); }
    static int size() { return CACHE.size(); }
    private static String keyOf(AuditRecord r) { return System.nanoTime() + "-" + r.hashCode(); }
}

// ─── Would be in HeapTrendMonitor.java in a real project ───
class HeapTrendMonitor {
    private static final Logger log = Logger.getLogger(HeapTrendMonitor.class.getName());
    private long previousBaselineMb = -1;
    private int risingSamples = 0;

    // Suggest a GC, then sample heap; a steadily rising post-GC baseline signals a leak.
    void sampleAfterGc(int retained) {
        System.gc(); // hint only; in prod we read post-GC usage from GC notifications
        Runtime rt = Runtime.getRuntime();
        long usedMb = (rt.totalMemory() - rt.freeMemory()) / (1024 * 1024);
        log.info(String.format("Post-GC heap baseline=%dMB  cachedRecords=%d", usedMb, retained));

        if (previousBaselineMb >= 0 && usedMb > previousBaselineMb) {
            risingSamples++;
            if (risingSamples >= 3) {
                log.warning("LEAK SUSPECTED: post-GC heap baseline rising for "
                        + risingSamples + " consecutive samples. Take a heap dump now.");
            }
        } else {
            risingSamples = 0;
        }
        previousBaselineMb = usedMb;
    }
}
